package com.bbms.repo;
import com.bbms.domain.*; import org.springframework.data.jpa.repository.*; import jakarta.persistence.LockModeType; import java.util.*;
public interface BloodRequestRepository extends JpaRepository<BloodRequest,Long>{List<BloodRequest> findAllByOrderByCreatedAtDesc(); List<BloodRequest> findByRequesterOrderByCreatedAtDesc(User requester); Optional<BloodRequest> findByDemoKey(String demoKey); boolean existsByPatientReference(String patientReference); long countByStatus(String status); long countByStatusAndDemoDataFalse(String status); long countByDemoDataTrue(); long count(); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select r from BloodRequest r where r.id=:id") Optional<BloodRequest> findByIdForUpdate(@org.springframework.data.repository.query.Param("id") Long id);}
